#include <iostream>
#include <vector>
#include <concepts>
template <std::integral T> class Buffer {
    std::vector<T> values_;

  public:
    void append(T x) { values_.push_back(x); }
    T sum() const {
        T n{};
        for (T x : values_) {
            n += x;
        }
        return n;
    }
};
int main() {
    Buffer<int> a;
    a.append(3);
    a.append(4);
    Buffer<long long> b;
    b.append(8);
    std::cout << a.sum() << ' ' << b.sum() << '\n';
}

